def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(obj, default=(0, 0)):
        try:
            x, y = obj
            return x, y
        except Exception:
            return default

    def move_toward(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def move_away(src, dst):
        sx, sy = src
        tx, ty = dst
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def manhattan(a, b):
        ax, ay = a
        bx, by = b
        return abs(ax - bx) + abs(ay - by)

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position"))
    ox, oy = pos(observation.get("opponent_position"), (sx, sy))
    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward((sx, sy), (ox, oy))
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
        target = max(corners, key=lambda c: manhattan(c, (ox, oy)))
        return move_toward((sx, sy), target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = None
        best_d = None
        for t in targets:
            tx, ty = pos(t, None)
            if tx is None:
                continue
            d = manhattan((sx, sy), (tx, ty))
            if best is None or d < best_d:
                best = (tx, ty)
                best_d = d
        if best is not None:
            return move_toward((sx, sy), best)
        if w and h:
            return move_toward((sx, sy), (w // 2, h // 2))
        return move_away((sx, sy), (ox, oy))

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = None
    best_d = None
    for r in resources:
        rx, ry = pos(r, None)
        if rx is None:
            continue
        d = manhattan((sx, sy), (rx, ry))
        if best is None or d < best_d:
            best = (rx, ry)
            best_d = d
    if best is not None:
        return move_toward((sx, sy), best)

    if w and h:
        center = (w // 2, h // 2)
        # If we are near the opponent, back off; otherwise drift to center.
        if manhattan((sx, sy), (ox, oy)) <= 2:
            return move_away((sx, sy), (ox, oy))
        return move_toward((sx, sy), center)

    return move_away((sx, sy), (ox, oy))

